  setViewMode(mode){this.viewMode=mode;const refineries=this.path==='/diesel-en590'&&mode==='refineries';this.portfolioButton.innerHTML=`${refineries?'▤ &nbsp; Refineries':'▦ &nbsp; Portfolio overview'} <span id="total"></span>`;this.total=this.portfolioButton.querySelector('#total');this.libraryLabel.textContent=refineries?'REFINERY LIBRARY':`${this.workspace.entity.toUpperCase()} LIBRARY`;this.search.placeholder=refineries?'Search refineries…':`Search ${this.workspace.entity.toLowerCase()}…`;this.list.setAttribute('aria-label',refineries?'Refineries':this.workspace.entity);this.saveState();this.render();}
