OpportunityPlatformApp.prototype.renderContactsPanel=function(record,card){const state=this.windWorkflow(this.detailRecordId);const contacts=[...(Array.isArray(record.contacts)?record.contacts:[]),...(state.contactsAdded||[])];const renderContact=contact=>{const email=String(contact.email||'').trim();const linkedin=this.safeUrl(contact.linkedin);const phones=Array.isArray(contact.phones)?contact.phones.filter(Boolean):contact.phone?[contact.phone]:[];const initials=(contact.name||'').split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase()||'—';return `<article class="wind-contact-entry"><span class="wind-contact-avatar" aria-hidden="true">${this.escape(initials)}</span><div class="wind-contact-copy"><h3>${this.escape(contact.name||'Unnamed contact')}</h3><p class="wind-contact-role">${this.escape(contact.title||contact.role||'Role not recorded')}</p>${contact.role&&contact.title?`<p class="wind-contact-caveat">${this.escape(contact.role)}</p>`:''}${email?`<p class="wind-contact-email"><a href="mailto:${this.escape(email)}">${this.escape(email)}</a></p>`:''}<p class="wind-contact-meta">${phones.length?this.escape(`Phone: ${phones.join(', ')}`):'Phone not recorded'}${linkedin?' · ':''}${linkedin?`<a href="${this.escape(linkedin)}" target="_blank" rel="noopener">LinkedIn profile ↗</a>`:''}</p>${contact.status?`<span class="wind-contact-status">${this.escape(contact.status)}</span>`:''}${contact.source?`<p class="wind-contact-source">${this.escape(contact.source)}</p>`:''}</div></article>`;};const form=`<form class="wind-contact-form" data-contact-form hidden><label>Name<input id="contact-name" required></label><label>Role / title<input id="contact-title"></label><label>Email<input id="contact-email" type="email"></label><label>Phone<input id="contact-phone" type="tel"></label><label class="wind-contact-wide">LinkedIn URL<input id="contact-linkedin" type="url"></label><label class="wind-contact-wide">Contact note<textarea id="contact-role" rows="3"></textarea></label><div class="wind-contact-wide wind-contact-save"><button type="button" class="primary" data-detail-action="save-contact">Save contact</button></div></form>`;return card('Project contacts',`<p class="wind-contacts-intro">Contact routes are imported research. A deliverable mailbox is not proof of a person-email match or current authority.</p><button type="button" class="quiet wind-add-contact" data-contact-form-toggle>+ Add contact</button>${form}<div class="wind-contacts-list">${contacts.length?contacts.map(renderContact).join(''):'<p class="wind-detail-empty">No contacts recorded.</p>'}</div>`,'wind-contacts-panel');};
