// Reusable contact-card view: rich research remains optional for legacy records.
OpportunityPlatformApp.prototype.contactEmailRoutes=function(contact){
 const routes=(Array.isArray(contact.emails)?contact.emails:[]).map(item=>typeof item==='string'?{email:item,type:'Email route; type not recorded'}:{...item});
 const legacy=String(contact.email||'').trim();
 if(legacy&&!routes.some(item=>String(item.email||'').trim().toLowerCase()===legacy.toLowerCase()))routes.unshift({email:legacy,type:contact.emailType||'Imported email route; type not recorded',source:contact.source||'',status:contact.status||'Person-email association not independently confirmed'});
 for(const route of contact.corporateRoutes||[]){
  const existing=routes.find(item=>String(item.email||'').trim().toLowerCase()===String(route.email||'').trim().toLowerCase());
  if(existing){existing.type=`${existing.type||'Existing email route'} / ${route.type}`;existing.status=[existing.status,route.status].filter(Boolean).join(' ');existing.source=existing.source||route.source;existing.routingSource=route.source;}
  else routes.push({...route});
 }
 return routes.filter((item,index,all)=>item.email&&all.findIndex(other=>String(other.email).trim().toLowerCase()===String(item.email).trim().toLowerCase())===index);
};
OpportunityPlatformApp.prototype.renderContactCard=function(contact){
 const escape=value=>this.escape(String(value??''));
 const externalUrl=value=>typeof value==='string'&&/^https?:\/\//i.test(value.trim())?this.safeUrl(value.trim()):'';
 const link=(url,label)=>{const href=externalUrl(url);return href?`<a href="${escape(href)}" target="_blank" rel="noopener">${escape(label)} ↗</a>`:'';};
 const initials=(contact.name||'').split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase()||'—';
 const routes=this.contactEmailRoutes(contact);
 const emailLines=routes.map(item=>{
  const value=String(item.email||'').trim();
  const candidate=/candidate|historical/i.test(item.type||'');
  const valid=/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(value);
  const result=EmailVerification.result(value);
  const pending=EmailVerification.pending.has(EmailVerification.normalize(value));
  const verification=valid&&candidate&&result?`<p class="contact-route-note reoon-result">${escape(EmailVerification.label(value))} · Mailbox check only; candidate identity unconfirmed.</p>`:valid&&!candidate?`<p class="contact-route-note reoon-result">${escape(EmailVerification.label(value))}</p><button type="button" class="quiet" data-reoon-email="${escape(value)}" data-reoon-source="${escape(item.source||contact.source||'')}" data-reoon-name="${escape(contact.name||'Unnamed contact')}" ${pending||result&&!EmailVerification.stale(result)?'disabled':''}>${pending?'Verifying automatically…':result?(EmailVerification.stale(result)?'Recheck with Reoon (uses credit)':'Reoon result saved'):'Verify with Reoon'}</button>`:'';
  return `<div class="contact-route${candidate?' contact-route-candidate':''}"><span class="contact-route-type">${escape(item.type||'Email route')}</span><div class="email-line">${valid&&!candidate?`<a class="email-value" href="mailto:${escape(value)}">${escape(value)}</a>`:`<span class="email-value">${escape(value)}</span>`}</div>${verification}${item.status?`<p class="contact-route-note">${escape(item.status)}</p>`:''}${item.date||item.source?`<p class="contact-route-note">${escape(item.date||'')}${item.date&&item.source?' · ':''}${link(item.source,'Email source')}</p>`:''}${item.routingSource&&item.routingSource!==item.source?`<p class="contact-route-note">${link(item.routingSource,'Corporate routing source')}</p>`:''}</div>`;
 }).join('')+`<p class="contact-route-note">${escape(contact.corporateRouteStatus||'Corporate route not audited for this saved contact; do not assume a personal email is a company route.')}</p>`;
 const phones=(Array.isArray(contact.phoneDetails)?contact.phoneDetails:[]).map(item=>({...item}));
 const numberKey=value=>String(value||'').replace(/[^\d+]/g,'');
 for(const value of [...(Array.isArray(contact.phones)?contact.phones:[]),contact.phone].filter(Boolean))if(!phones.some(item=>numberKey(item.number)===numberKey(value)))phones.push({number:value,type:'Imported phone; type not recorded'});
 const phoneLines=phones.map(item=>`<li><strong>${escape(item.type||'Telephone')}:</strong> ${escape(item.number)}${item.status?`<span class="contact-route-note">${escape(item.status)}</span>`:''}${item.source?`<span class="contact-route-note">${link(item.source,'Phone source')}</span>`:''}</li>`).join('');
 const research=contact.research&&typeof contact.research==='object'?contact.research:null;
 const hasLiveVerification=routes.some(item=>EmailVerification.result(item.email));
const researchList=(heading,items)=>Array.isArray(items)&&items.length?`<section class="contact-research-section"><h4>${escape(heading)}</h4><ul>${items.map(item=>{const entry=typeof item==='string'?{text:item}:item;return `<li>${escape(hasLiveVerification&&/No Reoon delivery check|No delivery check|no delivery verification/i.test(entry.text||'')?`Research snapshot before live Reoon check: ${entry.text}`:entry.text||'')}${entry.date||entry.source?`<span class="contact-route-note">${escape(entry.date||'')}${entry.date&&entry.source?' · ':''}${link(entry.source,'Finding source')}</span>`:''}</li>`;}).join('')}</ul></section>`:'';
 const researchHtml=research?`<section class="contact-research" aria-label="Research about ${escape(contact.name||'contact')}"><h4>About this contact</h4><dl class="contact-research-facts">${[['Company / affiliation',research.entity],['Project connection',research.projectConnection],['Decision relevance',research.decisionRelevance]].filter(([,value])=>value).map(([label,value])=>`<div><dt>${escape(label)}</dt><dd>${escape(value)}</dd></div>`).join('')}</dl>${researchList('Research findings',research.findings)}${researchList('Uncertainties / verification gaps',research.caveats)}${research.nextAction?`<section class="contact-research-section"><h4>Suggested next action</h4><p>${escape(research.nextAction)}</p></section>`:''}<p class="contact-research-meta">${escape(research.asOf?`Researched ${research.asOf}`:'Research date not recorded')}${research.confidence?` · Confidence: ${escape(research.confidence)}`:''}</p>${research.verification?`<p class="contact-route-note">${escape(research.verification)}</p>`:''}</section>`:'';
 const sourceEntries=[...(Array.isArray(contact.sources)?contact.sources:[]),...(contact.source?[{title:'Original contact source',url:contact.source}]:[])].map(item=>typeof item==='string'?{url:item}:item);
 const sources=sourceEntries.filter((item,index,all)=>item.url&&all.findIndex(other=>other.url===item.url)===index);
 const sourceHtml=sources.length?`<details class="contact-sources"><summary>Sources (${sources.length})</summary><ul>${sources.map(item=>`<li>${link(item.url,item.title||'Contact source')||escape(item.url)}${item.date?`<span class="contact-route-note">${escape(item.date)}</span>`:''}</li>`).join('')}</ul></details>`:'<p class="contact-route-note">Contact source not recorded</p>';
 const original=contact.originalImportedRecord||contact;
 return `<article class="card wind-contact-card" data-contact-name="${escape(contact.name||'Unnamed contact')}"><div class="avatar" aria-hidden="true">${escape(initials)}</div><h3>${escape(contact.name||'Unnamed contact')}</h3><p class="contact-role">${escape(contact.title||'Role not recorded')}</p>${contact.role?`<p>${escape(contact.role)}</p>`:''}<div class="contact-emails">${emailLines||'<p class="contact-route-note">No email recorded</p>'}</div>${research&&!routes.some(item=>item.type==='Personal email')?'<p class="contact-route-note">No public personal email found.</p>':''}<p class="muted contact-association">${escape(contact.status||'Person-email association not independently confirmed')}</p>${phones.length?`<ul class="contact-phones">${phoneLines}</ul>`:'<p class="muted">Phone not recorded</p>'}<div class="contact-link">${link(contact.linkedin,/candidate/i.test(`${contact.status||''} ${contact.role||''}`)?'LinkedIn profile — identity needs confirmation':'LinkedIn profile')||'LinkedIn not recorded'}</div>${(contact.links||[]).map(item=>`<div class="contact-link">${link(item.url,item.title||'Related link')}</div>`).join('')}${contact.notes?`<section class="contact-research-section"><h4>Contact notes</h4><p>${escape(contact.notes)}</p></section>`:''}${researchHtml}${sourceHtml}${contact.providerHistory?.length?`<details class="contact-original"><summary>Provider history</summary><pre>${escape(JSON.stringify(contact.providerHistory,null,2))}</pre></details>`:''}<details class="contact-original"><summary>${contact.originalImportedRecord?'Original imported record':'Saved contact record'}</summary><pre>${escape(JSON.stringify(original,null,2))}</pre></details></article>`;
};
OpportunityPlatformApp.prototype.renderContactsPanel=function(record){
 const state=this.windWorkflow(this.detailRecordId);
 const contacts=[...(Array.isArray(record.contacts)?record.contacts:[]),...(state.contactsAdded||[])];
 const form=`<form class="contact-editor" data-contact-form hidden><label>Name<input id="contact-name" required></label><label>Role / title<input id="contact-title"></label><label>Email<input id="contact-email" type="email"></label><label>Source URL<input id="contact-source" type="url" placeholder="https://…"></label><label>Phone<input id="contact-phone" type="tel"></label><label class="contact-editor-wide">LinkedIn URL<input id="contact-linkedin" type="url"></label><label class="contact-editor-wide">Contact note<textarea id="contact-role" rows="3"></textarea></label><div class="contact-editor-wide"><button type="button" class="primary" data-detail-action="save-contact">Save contact</button></div></form>`;
 const connection=EmailVerification.connection;
 return `<div class="contacts-scope" data-reoon-module="${this.escape(this.path||'')}" data-reoon-record="${this.escape(this.detailRecordId||'')}"><div class="contact-toolbar"><div><h2>Project contacts</h2><p class="muted">${contacts.length} contacts and routes · roles, research findings and source history are retained.</p></div><button type="button" class="primary" data-contact-form-toggle>+ Add contact</button></div><div class="notice">Published contact routes are not verified person-email matches. Shared inboxes, historical routes and unconfirmed candidates are labelled separately. Displaying cards never triggers verification charges or outreach.</div><p class="reoon-connection" role="status" aria-live="polite">${this.escape(EmailVerification.connectionLabel(connection))}</p><button type="button" class="quiet" data-reoon-connection>Check Reoon connection</button>${form}<div class="contact-grid">${contacts.length?contacts.map(contact=>this.renderContactCard(contact)).join(''):'<p class="wind-detail-empty">No contacts recorded.</p>'}</div></div>`;
};

// Save first, then verify the one explicitly entered address without blocking navigation.
const saveContactBeforeAutoVerification=OpportunityPlatformApp.prototype.handleDetailAction;
OpportunityPlatformApp.prototype.handleDetailAction=function(action){
 if(action!=='save-contact')return saveContactBeforeAutoVerification.call(this,action);
 const recordId=this.detailRecordId,module=this.path;
 const before=(this.windWorkflow(recordId).contactsAdded||[]).length;
 const saved=saveContactBeforeAutoVerification.call(this,action);
 const contacts=this.windWorkflow(recordId).contactsAdded||[];
 if(contacts.length>before&&contacts.at(-1)?.email)return EmailVerification.verifyAddedContact(module,recordId,contacts.at(-1));
 return saved;
};

document.addEventListener('click',async event=>{
 const button=event.target.closest('[data-reoon-email], [data-reoon-connection]');if(!button)return;
 const scope=button.closest('.contacts-scope');const feedback=scope?.querySelector('.reoon-connection');
 button.dataset.reoonBusy='true';
 button.disabled=true;if(feedback)feedback.textContent=button.dataset.reoonEmail?'Reoon Power verification in progress…':'Checking Reoon connection…';
 try{
  const email=button.dataset.reoonEmail;
  const data=await EmailVerification.request(email?'/api/reoon/verify':'/api/reoon/status',email?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({emails:[email],refresh:!!EmailVerification.result(email)&&EmailVerification.stale(EmailVerification.result(email)),context:{module:scope?.dataset.reoonModule,recordId:scope?.dataset.reoonRecord,name:button.dataset.reoonName,source:button.dataset.reoonSource,provenance:button.dataset.reoonSource?undefined:'manual-contact-entry',email}})}:{});
  if(email){
   for(const result of data.results||[])EmailVerification.results[EmailVerification.normalize(result.email)]=result;
   scope.querySelectorAll('[data-reoon-email]').forEach(item=>{const result=EmailVerification.result(item.dataset.reoonEmail);if(result){item.disabled=true;item.textContent='Reoon result saved';const label=item.previousElementSibling;if(label?.classList.contains('reoon-result'))label.textContent=EmailVerification.label(item.dataset.reoonEmail);}});
   document.dispatchEvent(new Event('reoon-results-updated'));if(feedback)feedback.textContent='Reoon result saved. Mailbox status does not prove identity or investment authority.';
  }else{EmailVerification.setConnection(data);}
 }catch(error){
  if(button.dataset.reoonEmail){try{await EmailVerification.sync();}catch{/* Saved results remain available during an outage. */}}
  else EmailVerification.setConnection({connected:false,error:error.message});
  if(feedback)feedback.textContent=error.message;
 }
 finally{delete button.dataset.reoonBusy;const result=EmailVerification.result(button.dataset.reoonEmail);if(!button.dataset.reoonEmail||!result||EmailVerification.stale(result))button.disabled=false;}
});
document.addEventListener('click',event=>{const toggle=event.target.closest('.contacts-scope [data-contact-form-toggle]');if(!toggle)return;const form=toggle.closest('.contacts-scope')?.querySelector('[data-contact-form]');if(!form)return;form.hidden=!form.hidden;toggle.textContent=form.hidden?'+ Add contact':'Cancel';});
OpportunityPlatformApp.prototype.renderSourcesPanel=function(record){const state=this.windWorkflow(this.detailRecordId);const sources=Array.isArray(record.sources)?record.sources:[];const importedDate=record.source?.date||'2026-10-15';const register=sources.length?sources.map(source=>{const href=this.safeUrl(source.url);return `<div class="source">${href?`<a href="${this.escape(href)}" target="_blank" rel="noopener">${this.escape(source.title||'Source')} ↗</a>`:`<strong>${this.escape(source.title||'Source')}</strong>`}<small>${this.escape(source.date||'Publication date not checked')} · imported ${this.escape(importedDate)} · not revalidated</small>${source.url?`<small>${this.escape(source.url)}</small>`:''}</div>`}).join(''):'<p class="wind-detail-empty">No sources recorded.</p>';return `<div class="wind-sources-scope"><section class="card wind-sources-card"><h2>Research brief</h2><p>${this.escape(this.detailValue(record.summary))}</p><p class="muted">This is a structured consolidation of available earlier research, not a newly completed deep-research report. Source content, dates, current job titles and project availability must be rechecked.</p>${this.detailList(record.gaps,'No evidence gaps recorded.')}</section><section class="card wind-sources-card"><h2>Source register</h2>${register}</section><section class="card wind-sources-card"><h2>Additional research notes</h2><label class="sr-only" for="research-notes">Additional research notes</label><textarea id="research-notes" placeholder="Add dated research, citations and conflicting information…">${this.escape(state.researchNotes||'')}</textarea><p><button type="button" class="primary" data-detail-action="save-research-notes">Save research notes</button></p></section></div>`;};
const renderWindPanelWithContacts=OpportunityPlatformApp.prototype.renderWindPanel;
OpportunityPlatformApp.prototype.renderWindPanel=function(record,tab){if(tab==='sources')return this.renderSourcesPanel(record);return renderWindPanelWithContacts.call(this,record,tab);};
const handleDetailActionWithContacts=OpportunityPlatformApp.prototype.handleDetailAction;
OpportunityPlatformApp.prototype.handleDetailAction=function(action){if(action==='save-research-notes'){const notes=this.root.querySelector('#research-notes')?.value||'';this.saveWindWorkflow(this.detailRecordId,{researchNotes:notes});return;}return handleDetailActionWithContacts.call(this,action);};
OpportunityPlatformApp.prototype.renderOutreachPanel=function(record){const state=this.windWorkflow(this.detailRecordId);const title=record.name||'this project';const baseDraft=`Subject: ${title} — Strategic Investment and Partnership\n\nDear Project Team,\n\nI am advising an established wind-energy developer on selected international opportunities for equity investment, joint ventures and strategic participation.\n\nI am contacting you regarding ${title} and would appreciate a brief, non-confidential overview of the project’s current development stage, ownership structure, capital requirements and available partnership opportunities.\n\nFor your review, please find below a brief profile of the developer:\n\nOur partner is a renewable-energy developer with experience in utility-scale wind and hybrid projects, covering development, engineering, construction, grid integration, commissioning and operations. It is currently evaluating equity investments, joint ventures and strategic participation in suitable projects.\n\nPlease direct me to the appropriate person responsible for the project’s partner process.\n\nKind regards,`;const draft=state.outreachDraft||baseDraft;const contacts=(Array.isArray(record.contacts)?record.contacts:[]).filter(contact=>String(contact.email||'').includes('@'));const recipientRows=contacts.length?contacts.map(contact=>`<tr><td><input type="checkbox" aria-label="Select ${this.escape(contact.email)}"></td><td><strong>${this.escape(contact.name||'Unnamed contact')}</strong><br><small class="muted">${this.escape(contact.title||contact.role||'Role not recorded')}</small></td><td>${this.escape(contact.email)}<br><span class="outreach-recipient-status">Imported route · not revalidated</span></td></tr>`).join(''):'<tr><td colspan="3" class="wind-detail-empty">No email routes recorded.</td></tr>';return `<div class="wind-outreach-grid"><div><section class="card wind-outreach-card"><h2>Draft an introductory enquiry</h2><p class="muted">Editable draft for this project. Start with a “Subject: …” line. No email is sent from 8181 until a sending integration is deliberately connected.</p><label class="sr-only" for="outreach-draft">Email draft</label><textarea id="outreach-draft" rows="15">${this.escape(draft)}</textarea><p><button type="button" class="primary" data-detail-action="save-outreach-draft">Save draft</button> <button type="button" class="quiet" data-detail-action="copy-outreach-draft">Copy draft</button></p></section><section class="card wind-outreach-card wind-pulse-card"><h2>Send with Pulse</h2><p class="muted">Send from the Wind Projects desk (localhost:9601). Sends appear here automatically.</p><div class="outreach-mode"><label><input type="radio" checked disabled> One by one (personal greeting)</label><label><input type="radio" disabled> One email (To / CC / BCC)</label></div><table class="outreach-recipients"><tbody>${recipientRows}</tbody></table><p><button type="button" class="primary" disabled title="Send from the Wind Projects desk (localhost:9601). Sends appear here automatically.">Send with Pulse</button></p><div class="outreach-preview"><p class="muted">Preview · a connected sender would add its signature below.</p><p class="outreach-preview-subject"><strong>Subject:</strong> ${this.escape((draft.split('\n')[0]||'').replace(/^Subject:\s*/,''))}</p></div><h3>Sent history</h3><p class="muted">No emails sent from this project in 8181.</p></section></div><aside><section class="card wind-outreach-card"><h2>Your relationship workflow</h2><div class="outreach-form-row"><label>Stage<select id="outreach-stage">${['Not contacted','Draft prepared','Contacted','Awaiting reply','NDA discussion','Under review','On hold','Closed'].map(value=>`<option${(state.outreachStage||'Not contacted')===value?' selected':''}>${value}</option>`).join('')}</select></label><label>Follow-up date<input id="outreach-followup" type="date" value="${this.escape(state.outreachFollowup||'')}"></label></div><label>Email status<select id="outreach-email-status">${['Not sent','Email sent','Response received'].map(value=>`<option${(state.outreachEmailStatus||'Not sent')===value?' selected':''}>${value}</option>`).join('')}</select></label><label>Conversation notes<textarea id="outreach-notes" rows="7">${this.escape(state.outreachNotes||'')}</textarea></label><p><button type="button" class="primary" data-detail-action="save-outreach-workflow">Save workflow</button></p><p class="outreach-status-help">Dates and outreach status are reminders in this workspace only. There are no scheduled notifications.</p></section><section class="card wind-outreach-card"><h2>Storage</h2><p class="muted">Notes, priorities and drafts are stored in this browser on this localhost origin. Use Export workspace to keep a portable backup. They do not sync to other browsers or services.</p></section></aside></div>`;};
const renderWindPanelWithSources=OpportunityPlatformApp.prototype.renderWindPanel;
OpportunityPlatformApp.prototype.renderWindPanel=function(record,tab){if(tab==='outreach')return this.renderOutreachPanel(record);return renderWindPanelWithSources.call(this,record,tab);};
const handleDetailActionWithSources=OpportunityPlatformApp.prototype.handleDetailAction;
OpportunityPlatformApp.prototype.handleDetailAction=function(action){
  if(action==='save-outreach-draft'){this.saveWindWorkflow(this.detailRecordId,{outreachDraft:this.root.querySelector('#outreach-draft')?.value||''});return;}
  if(action==='save-outreach-workflow'){
    this.saveWindWorkflow(this.detailRecordId,{outreachStage:this.root.querySelector('#outreach-stage')?.value||'Not contacted',outreachFollowup:this.root.querySelector('#outreach-followup')?.value||'',outreachEmailStatus:this.root.querySelector('#outreach-email-status')?.value||'Not sent',outreachNotes:this.root.querySelector('#outreach-notes')?.value||''});
    const status=this.root.querySelector('.outreach-save-status');if(status)status.textContent='Workflow saved. Sidebar status updated.';
    return;
  }
  if(action==='copy-outreach-draft'){navigator.clipboard?.writeText(this.root.querySelector('#outreach-draft')?.value||'');return;}
  return handleDetailActionWithSources.call(this,action);
};

const renderOutreachPanelWithImportedHistory=OpportunityPlatformApp.prototype.renderOutreachPanel;
OpportunityPlatformApp.prototype.renderImportedOutreachHistory=function(){
  const history=WindSendHistory.input(this.windWorkflow(this.detailRecordId),this.sendHistory?.projects?.[this.detailRecordId])?.outreachHistory;
  if(!Array.isArray(history)||!history.length)return '<p class="muted">No sends recorded for this project.</p>';
  return `<ul class="outreach-history-list">${history.map(entry=>{const results=Array.isArray(entry.results)?entry.results:[];const recipients=Array.isArray(entry.recipients)?entry.recipients:[];const overrides=new Set((entry.catchAllOverride||[]).map(email=>String(email).toLowerCase()));const sent=results.filter(result=>result.status==='sent').flatMap(result=>result.emails||[]);const blocked=results.filter(result=>result.status==='blocked').flatMap(result=>result.emails||[]);const failed=results.filter(result=>!['sent','blocked'].includes(result.status)).flatMap(result=>result.emails||[]);const recipientText=recipients.map(recipient=>`${recipient.field?`${String(recipient.field).toUpperCase()} `:''}${recipient.email}${overrides.has(String(recipient.email).toLowerCase())?' · Catch-all, delivery unconfirmed':''}`).join(', ');return `<li><small>${this.escape(new Date(entry.at).toLocaleString('en-GB',{timeZone:'Asia/Dubai'}))} (Dubai) · ${this.escape(entry.mode==='together'?'one email':'one by one')}${entry.origin?` · ${this.escape(entry.origin)}`:''}</small><p><strong>${this.escape(entry.subject||'Subject not recorded')}</strong></p><p class="muted">${this.escape(recipientText)}</p>${sent.length?`<p class="outreach-history-success">Sent: ${this.escape(sent.join(', '))}</p>`:''}${blocked.length?`<p class="outreach-history-blocked">Blocked: ${this.escape(blocked.join(', '))}</p>`:''}${failed.length?`<p class="outreach-history-blocked">Failed: ${this.escape(failed.join(', '))}</p>`:''}${entry.status==='sending'?'<p class="outreach-history-blocked">Outcome not confirmed — check Pulse Sent before sending again.</p>':''}</li>`;}).join('')}</ul>`;
};
OpportunityPlatformApp.prototype.renderOutreachPanel=function(record){
  const markup=renderOutreachPanelWithImportedHistory.call(this,record);
  const history=this.renderImportedOutreachHistory();
  return markup.replace('<h3>Sent history</h3><p class="muted">No emails sent from this project in 8181.</p>',`<h3>Send history (from Wind Projects desk)</h3><div class="outreach-send-history">${this.renderSendHistorySync()}${history}</div>`).replace('<p class="outreach-status-help">Dates and outreach status are reminders in this workspace only. There are no scheduled notifications.</p>','<p class="outreach-status-help"><span class="email-status-dot sent" aria-hidden="true"></span> Email sent <span class="email-status-dot responded" aria-hidden="true"></span> Response received. Save workflow to update the sidebar. These are recorded statuses, not automatic inbox tracking.</p><p class="outreach-save-status" role="status" aria-live="polite"></p>');
};

OpportunityPlatformApp.prototype.renderSendHistorySync=function(){
  const state=this.sendHistory;
  const synced=state?.syncedAt?`${new Date(state.syncedAt).toLocaleString('en-GB',{timeZone:'Asia/Dubai'})} (Dubai)`:'not yet';
  const notice=state?.notices?.length?state.notices.map(text=>`<p class="muted">${this.escape(text)}</p>`).join(''):state&&!state.available?'<p class="muted">Send history from the Wind Projects desk is not available right now.</p>':'';
  return `<p class="muted outreach-send-sync">Last synced: ${this.escape(synced)} <button type="button" class="quiet" data-detail-action="refresh-send-history">Refresh send history</button></p>${notice}`;
};
OpportunityPlatformApp.prototype.loadSendHistory=function(){
  if(this.pulse)return this.pulse.refresh();
  if(this.sendHistoryLoading)return this.sendHistoryLoading;
  this.sendHistoryLoading=(async()=>{
    let data=null;
    try{const response=await fetch('/api/wind-projects/outreach-status',{cache:'no-store'});if(response.ok)data=await response.json();}catch{}
    const available=data?.available===true&&!!data.projects&&typeof data.projects==='object';
    this.sendHistory={available,projects:available?data.projects:{},syncedAt:available?(data.generatedAt||new Date().toISOString()):this.sendHistory?.syncedAt||null};
    if(this.sidebar){this.sidebar.sendHistory=this.sendHistory.projects;this.sidebar.refreshOutreachSignals();}
    const section=this.root?.querySelector?.('.outreach-send-history');
    if(section)section.innerHTML=this.renderSendHistorySync()+this.renderImportedOutreachHistory();
    return this.sendHistory;
  })().finally(()=>{this.sendHistoryLoading=null;});
  return this.sendHistoryLoading;
};
const handleDetailActionWithSendHistory=OpportunityPlatformApp.prototype.handleDetailAction;
OpportunityPlatformApp.prototype.handleDetailAction=function(action){
  if(action==='refresh-send-history'){this.loadSendHistory();return;}
  if((action==='pulse-send'||action==='pulse-send-anyway')&&this.pulse){const row=this.rows.find(item=>item.id===this.detailRecordId);if(action==='pulse-send-anyway')this.pulse.sendAnyway();else this.pulse.send(row?.source||row||{});return;}
  return handleDetailActionWithSendHistory.call(this,action);
};

/* With a Pulse controller (shell.js), the disabled card becomes a live "Send with Pulse" card for this module. */
